import {BloodUnit, BloodGroup, BloodComponent, BloodUnitStatus} from './contracts.js';
export function validateUnit(input:Partial<BloodUnit>):string[] { const e:string[]=[]; if(!input.code?.trim())e.push('code'); if(!['O+','O-','A+','A-','B+','B-','AB+','AB-'].includes(input.bloodGroup as string))e.push('bloodGroup'); if(!['Glóbulos rojos','Plaquetas','Plasma'].includes(input.component as string))e.push('component'); if(!input.expiresAt)e.push('expiresAt'); return e; }
export function calculateInventorySummary(units:BloodUnit[]) { const today=Date.now(); const available=units.filter(u=>u.status==='available' && Date.parse(u.expiresAt)>=today); const byGroup=available.reduce<Record<string,number>>((a,u)=>(a[u.bloodGroup]=(a[u.bloodGroup]||0)+1,a),{}); return {total:available.length, byGroup, expiringSoon:available.filter(u=>Date.parse(u.expiresAt)-today<7*86400000).length}; }
